# Calcul analytique vs itératif de la somme géométrique :
def somme_geo_iterative(q: float, n: int) -> float:
    return sum(q**i for i in range(n + 1))

def somme_geo_fermee(q: float, n: int) -> float:
    return (1 - q**(n + 1)) / (1 - q) if q != 1 else n + 1

# Test n=10, q=2 -> 2^11 - 1 = 2047
assert somme_geo_iterative(2, 10) == somme_geo_fermee(2, 10) == 2047

